// P2.2 O1 — golden cross-check against the astro.ts fixture (copied, not
// forked). Proves gmst/sunDirection/observerTeme produce the exact same
// numbers as the pre-orbital-core implementations they replace.
//
// __fixtures__/astro-golden.json is a plain copy of
// packages/backend/src/analytic/astro-golden.json (generated by
// packages/frontend/scripts/gen-astro-golden.ts via the real client path).
// Same tolerances as the backend's tests/analytic/astro.test.ts golden check.

import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, resolve } from 'node:path';
import { describe, it } from 'node:test';
import { gmst, sunDirection, observerTeme } from './index.js';

const __dirname = dirname(fileURLToPath(import.meta.url));
const GOLDEN_PATH = resolve(__dirname, './__fixtures__/astro-golden.json');

interface GoldenRow {
  iso: string;
  tMs: number;
  gast: number;
  sun: { x: number; y: number; z: number };
  observers: { latDeg: number; lonDeg: number; altKm: number; teme: { x: number; y: number; z: number } }[];
}

const golden = JSON.parse(readFileSync(GOLDEN_PATH, 'utf8')) as { rows: GoldenRow[] };

function assertCloseRel(actual: number, expected: number, msg: string, relTol = 1e-9): void {
  const diff = Math.abs(actual - expected);
  // Near-zero expected values (e.g. z=0 at the equator) need an absolute floor —
  // a pure relative tolerance is meaningless against zero.
  const tol = Math.max(relTol, relTol * Math.abs(expected));
  assert.ok(diff <= tol, `${msg}: expected ${expected}, got ${actual} (diff ${diff}, tol ${tol})`);
}

describe('orbital-core golden cross-check (ported from backend astro.test.ts)', () => {
  it('fixture has rows (else re-copy from backend astro-golden.json)', () => {
    assert.ok(golden.rows.length > 0, 'astro-golden.json must have rows');
  });

  for (const row of golden.rows) {
    describe(`instant ${row.iso}`, () => {
      it('gmst matches', () => {
        assertCloseRel(gmst(row.tMs), row.gast, 'gmst');
      });

      it('sunDirection matches', () => {
        const s = sunDirection(row.tMs);
        assertCloseRel(s.x, row.sun.x, 'sun.x');
        assertCloseRel(s.y, row.sun.y, 'sun.y');
        assertCloseRel(s.z, row.sun.z, 'sun.z');
      });

      for (const obs of row.observers) {
        it(`observerTeme(...).position matches (lat=${obs.latDeg}, lon=${obs.lonDeg}, alt=${obs.altKm})`, () => {
          const t = observerTeme({ latDeg: obs.latDeg, lonDeg: obs.lonDeg, altKm: obs.altKm }, row.tMs).position;
          assertCloseRel(t.x, obs.teme.x, 'observer.x');
          assertCloseRel(t.y, obs.teme.y, 'observer.y');
          assertCloseRel(t.z, obs.teme.z, 'observer.z');
        });
      }
    });
  }
});
